# verify wythoff via DP for all a,b <=25 and compare cold set & lexicographic move
PHI=(1+5**0.5)/2
def is_cold(x,y):
    if x>y: x,y=y,x
    if x==0: return y==0
    n=y-x
    return int(n*PHI)==x and int(n*PHI*PHI)==y
DP=[[False]*26 for _ in range(26)]
for x in range(26):
    for y in range(26):
        if x==0 and y==0: DP[x][y]=False; continue
        win=False
        for i in range(1,x+1):
            if DP[x-i][y]: win=True;break
        if not win:
            for j in range(1,y+1):
                if DP[x][y-j]: win=True;break
        if not win:
            for i in range(1,min(x,y)+1):
                if DP[x-i][y-i]: win=True;break
        DP[x][y]=win
bad=0
for x in range(26):
    for y in range(26):
        if DP[x][y]==False and not is_cold(x,y): bad+=1; print('mismatch cold',x,y)
        if DP[x][y]==True and is_cold(x,y): bad+=1; print('mismatch win',x,y)
print('bad',bad)
# compare full answers
for a in range(1,26):
    for b in range(1,26):
        if DP[a][b]: continue
        # losing, check output LOSE
        continue
# lexicographic minimal move from formula vs DP
def answer_dp(a,b):
    if not DP[a][b]: return 'LOSE'
    for i in range(a+1):
        for j in range(b+1):
            if i==0 and j==0: continue
            if not DP[a-i][b-j]: return f'WIN {i} {j}'
    return 'LOSE'
def answer_f(a,b):
    if is_cold(a,b): return 'LOSE'
    for i in range(a+1):
        for j in range(b+1):
            if i==0 and j==0: continue
            if is_cold(a-i,b-j): return f'WIN {i} {j}'
    return 'LOSE'
for a in range(1,26):
    for b in range(1,26):
        if answer_dp(a,b)!=answer_f(a,b):
            print('diff',a,b,answer_dp(a,b),answer_f(a,b)); bad+=1
print('final bad',bad)
